-- The procedure these files implement is docs/data-migration.md.

-- Reconciliation. The old database stays read-only until every check here passes
-- (docs/data-migration.md Decision 3).
--
-- Every aggregate below is `sum(col::numeric)`, never `sum(col::float8)`. Floating
-- addition is not associative, so a float sum over 19 GB depends on the order the
-- rows arrive in and on how many parallel workers the planner chose — the two
-- sides would differ in the last bits and the operator would be left deciding
-- whether 1e-9 is a migration defect. numeric is exact and order-independent, so
-- the comparison can be `IS DISTINCT FROM` with no tolerance, which is the only
-- kind of comparison that cannot be argued with.

CREATE TABLE w9.recon (
    side       text NOT NULL CHECK (side IN ('old', 'new')),
    station_id text NOT NULL,
    yr         int  NOT NULL,
    metric     text NOT NULL,
    rows       bigint,
    non_null   bigint,
    total      numeric,
    lo         numeric,
    hi         numeric,
    PRIMARY KEY (side, station_id, yr, metric)
);

-- The old side's digest, over 197 numeric metrics. One pass; the LATERAL
