CREATE FUNCTION w9.digest_body(side text, t0 timestamptz, t1 timestamptz) RETURNS text
LANGUAGE plpgsql STABLE AS $fn$
DECLARE tbl text; key text; aggs text; vals text;
BEGIN
    IF side = 'old' THEN tbl := 'weather';      key := 'stationname';
    ELSE                 tbl := 'observations'; key := 'station_id';
    END IF;
    SELECT string_agg(format('count(%1$I) AS %1$I_nn, sum(%1$I::numeric) AS %1$I_t, '
                             'min(%1$I)::numeric AS %1$I_lo, max(%1$I)::numeric AS %1$I_hi',
                             d.column_name), ', ' ORDER BY d.ord),
           string_agg(format('(%1$L, z.%2$I_nn, z.%2$I_t, z.%2$I_lo, z.%2$I_hi)',
                             d.column_name, d.column_name), ', ' ORDER BY d.ord)
      INTO aggs, vals
      FROM w9.digest_metric d
      JOIN w9.source_column s ON s.column_name = d.column_name;
    IF aggs IS NULL THEN
        RAISE EXCEPTION 'w9.source_column is empty; load the inventory first';
    END IF;
    RETURN format(
        'SELECT %L, z.k, z.yr, v.metric, z.n, v.non_null, v.total, v.lo, v.hi '
        'FROM (SELECT %I AS k, extract(year from time)::int AS yr, count(*) AS n, %s '
        'FROM %I WHERE time >= %L AND time < %L GROUP BY 1, 2) z, '
        'LATERAL (VALUES %s) v(metric, non_null, total, lo, hi)',
        side, key, aggs, tbl, t0, t1, vals);
END $fn$;

COMMENT ON FUNCTION w9.digest_body(text, timestamptz, timestamptz) IS
    'One sequential pass per side. The LATERAL unpivots columns a single GROUP BY
     already produced, so this does not scan once per metric.';

-- The old side groups by stationname because that is the only station key the old
-- table has. migrate-from-go.sh maps it to station_id through w9.station_map on the
-- way in, so the two sides of this join are in the same namespace.
CREATE VIEW w9.recon_report AS
SELECT coalesce(o.station_id, n.station_id) AS station_id,
       coalesce(o.yr, n.yr)              AS yr,
       coalesce(o.metric, n.metric)      AS metric,
       o.rows AS old_rows, n.rows AS new_rows,
       o.non_null AS old_non_null, n.non_null AS new_non_null,
       o.total AS old_total, n.total AS new_total,
       o.lo AS old_lo, n.lo AS new_lo,
       o.hi AS old_hi, n.hi AS new_hi,
       CASE WHEN n.station_id IS NULL THEN 'missing_in_new'
            WHEN o.station_id IS NULL THEN 'extra_in_new'
            WHEN o.rows IS DISTINCT FROM n.rows THEN 'row_count'
            WHEN o.non_null IS DISTINCT FROM n.non_null THEN 'non_null_count'
            WHEN o.total IS DISTINCT FROM n.total THEN 'sum'
            WHEN o.lo IS DISTINCT FROM n.lo THEN 'min'
            WHEN o.hi IS DISTINCT FROM n.hi THEN 'max'
            ELSE 'ok' END AS verdict
  FROM (SELECT * FROM w9.recon WHERE side = 'old') o
  FULL OUTER JOIN (SELECT * FROM w9.recon WHERE side = 'new') n
    USING (station_id, yr, metric);

CREATE FUNCTION w9.assert_reconciled() RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE n bigint; sample text;
BEGIN
    SELECT count(*), string_agg(format('%s/%s/%s: %s', station_id, yr, metric, verdict),
                                '; ' ORDER BY station_id, yr, metric)
      INTO n, sample
      FROM (SELECT * FROM w9.recon_report WHERE verdict <> 'ok' LIMIT 20) d;
    IF NOT EXISTS (SELECT 1 FROM w9.recon) THEN
        RAISE EXCEPTION 'w9.recon is empty: nothing was reconciled'
            USING HINT = 'a reconciliation that ran against no rows is not a pass';
    END IF;
    IF n > 0 THEN
        RAISE EXCEPTION 'reconciliation found % mismatching (station, year, metric) rows: %',
            n, sample;
    END IF;
END $fn$;

-- ------------------------------------------------------------------
-- The check the other ones cannot make: does the *new hierarchy* reproduce the old
-- daily view's numbers? The digests above compare raw against raw, which proves the
-- rows moved. This compares observations_1d, built bottom-up through four levels,
-- against weather_1d, built in one step from raw — so it also catches the class of
-- defect D-12 and D-14 exist for.
--
-- The old view's daily mean is `avg(col)` over raw; the new one is
-- mw_mean(col_sum, col_count) over three intermediate levels. D-14 widened the
-- accumulator specifically so these agree exactly, so the comparison is exact to
-- 1e-9 relative — which is float4's own representable precision, not a tolerance
-- chosen to make the test pass.
-- ------------------------------------------------------------------

CREATE TABLE w9.rollup_recon (
    station_id text NOT NULL,
    bucket     timestamptz NOT NULL,
    metric     text NOT NULL,
    stat       text NOT NULL,
    old_value  double precision,
    new_value  double precision,
    -- Readings in the bucket, which is what bounds the old side's error for any
    -- statistic the Go views accumulated in `real`. See tol_model below.
    n_readings bigint,
    -- 'exact'             the old view stored this at double precision or at the
    --                     column's own width and computed it in one operation:
    --                     avg(real) accumulates in float8 and returns float8,
    --                     min and max are the value itself. Zero tolerance.
    -- 'float4_accumulated' the old view both accumulated AND stored this in
    --                     `real`: sum(real) returns real, and the Go
    --                     circular_avg_state declares sin_sum, cos_sum and even
    --                     its count as `real`. Error grows with the number of
    --                     additions, which is exactly the defect D-14 widened the
    --                     accumulator to avoid — so here the NEW value is the
    --                     accurate one and the bound is on how wrong the OLD one
    --                     is allowed to be: n * 2^-24 relative.
    tol_model  text NOT NULL DEFAULT 'exact'
        CHECK (tol_model IN ('exact', 'float4_accumulated')),
    PRIMARY KEY (station_id, bucket, metric, stat)
);

CREATE VIEW w9.rollup_report AS
SELECT *,
       CASE tol_model
            WHEN 'exact' THEN 0.0
            ELSE coalesce(n_readings, 1) * 5.96e-8
       END * greatest(abs(coalesce(old_value, 0)), abs(coalesce(new_value, 0)), 1)
         AS tolerance,
       CASE WHEN old_value IS NULL AND new_value IS NULL THEN 'ok'
            WHEN old_value IS NULL OR  new_value IS NULL THEN 'one_side_null'
            WHEN tol_model = 'exact'
                 THEN CASE WHEN old_value = new_value THEN 'ok' ELSE 'differs' END
            WHEN abs(old_value - new_value)
                 <= coalesce(n_readings, 1) * 5.96e-8
                    * greatest(abs(old_value), abs(new_value), 1) THEN 'ok'
            ELSE 'differs' END AS verdict
  FROM w9.rollup_recon;

-- 5.96e-8 is 2^-24, half an ulp of float4's 24-bit mantissa. Multiplying it by the
-- number of additions is the standard worst-case bound for a running sum in that
-- width. It is not a tolerance chosen to make the check pass: 'exact' rows get zero
-- tolerance and must agree bit for bit, and the two statistics that get a bound are
-- the two where the Go schema's own accumulator width makes exact agreement
-- arithmetically impossible.

-- ------------------------------------------------------------------
-- Spot checks on values a human remembers. Row counts and sums prove the bytes
-- arrived; an extreme and its timestamp prove they arrived meaning the same thing.
-- Both sides emit the same shape and the operator reads the two tables side by
-- side, because "was the hottest day of 2025 the day I remember?" is not a question
-- a constraint can answer.
-- ------------------------------------------------------------------

-- Six named extremes per station per year, with the timestamp that produced each.
-- One statement per (metric, direction) because an extreme needs DISTINCT ON per
-- group, which no single GROUP BY gives; seven metrics by two directions is
-- fourteen index scans, not fourteen table scans.
--
-- `side` is emitted as the first column so that the old side — which arrives over a
-- COPY pipe and cannot have a column added on the way in — and the new side have
-- exactly the same shape.
CREATE FUNCTION w9.extreme_sql(side text, col text, dir text,
                            t0 timestamptz, t1 timestamptz) RETURNS text
LANGUAGE sql STABLE AS $fn$
    SELECT format(
        'SELECT %L::text AS side, %I AS station, extract(year from time)::int AS yr, '
        '%L AS metric, %L AS dir, %I::double precision AS value, time AS at FROM ('
        '  SELECT DISTINCT ON (%I, extract(year from time)) %I, time, %I '
        '    FROM %I WHERE time >= %L AND time < %L AND %I IS NOT NULL '
        '   ORDER BY %I, extract(year from time), %I %s, time ASC) q',
        side,
        CASE WHEN side = 'old' THEN 'stationname' ELSE 'station_id' END,
        col, dir, col,
        CASE WHEN side = 'old' THEN 'stationname' ELSE 'station_id' END,
        CASE WHEN side = 'old' THEN 'stationname' ELSE 'station_id' END, col,
        CASE WHEN side = 'old' THEN 'weather' ELSE 'observations' END,
        t0, t1, col,
        CASE WHEN side = 'old' THEN 'stationname' ELSE 'station_id' END,
        col, CASE WHEN upper(dir) = 'MAX' THEN 'DESC' ELSE 'ASC' END)
$fn$;

CREATE TABLE w9.extreme (
    side    text NOT NULL CHECK (side IN ('old', 'new')),
    station text NOT NULL,
    yr      int  NOT NULL,
    metric  text NOT NULL,
    dir     text NOT NULL,
    value   double precision,
    at      timestamptz,
    PRIMARY KEY (side, station, yr, metric, dir)
);

CREATE VIEW w9.extreme_report AS
SELECT coalesce(o.station, n.station) AS station,
       coalesce(o.yr, n.yr) AS yr,
       coalesce(o.metric, n.metric) AS metric,
       coalesce(o.dir, n.dir) AS dir,
       o.value AS old_value, o.at AS old_at,
       n.value AS new_value, n.at AS new_at,
       CASE WHEN o.value IS DISTINCT FROM n.value THEN 'value_differs'
            WHEN o.at IS DISTINCT FROM n.at THEN 'timestamp_differs'
            ELSE 'ok' END AS verdict
  FROM (SELECT * FROM w9.extreme WHERE side = 'old') o
  FULL OUTER JOIN (SELECT * FROM w9.extreme WHERE side = 'new') n
    USING (station, yr, metric, dir);

-- The metrics worth spot-checking: the ones a person has an opinion about.
-- Keyed by (col, dir), not by col: the same metric is spot-checked in both
-- directions, and a primary key on col alone silently keeps one of the two.
CREATE TABLE w9.spot_metric (col text NOT NULL, dir text NOT NULL,
                         PRIMARY KEY (col, dir));
INSERT INTO w9.spot_metric (col, dir) VALUES
    ('outtemp', 'max'), ('outtemp', 'min'), ('windspeed', 'max'),
    ('barometer', 'max'), ('barometer', 'min'), ('dayrain', 'max'),
    ('snowdepth', 'max')
ON CONFLICT DO NOTHING;
